<style>
.fl-gallery{font-family:var(--feega-font);font-size:var(--feega-text-body);line-height:1.5;letter-spacing:var(--feega-tracking);color:var(--feega-fg);background:var(--feega-bg);-webkit-font-smoothing:antialiased}
:where(.fl-gallery) *,:where(.fl-gallery) *::before,:where(.fl-gallery) *::after{box-sizing:border-box}
:where(.fl-gallery) :is(h1,h2,h3,h4,p,ul,ol,figure,blockquote,dl,dd){margin:0}
:where(.fl-gallery) a{color:inherit;text-decoration:none}
:where(.fl-gallery) :focus-visible{outline:2px solid var(--feega-focus);outline-offset:3px}
.fl-container{width:min(var(--feega-max-width),100% - 2 * var(--feega-gutter));margin-inline:auto}
.fl-px{display:block;flex:none;width:1em;height:auto;fill:currentColor;shape-rendering:crispEdges}
.fl-title{font-family:var(--feega-font-display);font-size:var(--feega-text-title);font-weight:500;line-height:0.95;letter-spacing:var(--feega-tracking-tight);text-wrap:balance}
.fl-lead{max-width:34rem;font-size:var(--feega-text-lg);line-height:1.4;color:var(--feega-fg-muted);text-wrap:pretty}
.fl-eyebrow{display:inline-flex;align-items:center;gap:var(--feega-space-2);font-family:var(--feega-font-mono);font-size:var(--feega-text-xs);letter-spacing:0.02em;color:var(--feega-fg-muted);text-transform:uppercase}
.fl-eyebrow::before{content:"";width:6px;height:6px;background:var(--feega-accent)}
.fl-dots{background-image:radial-gradient(var(--feega-dot) 1px,transparent 1.5px);background-size:14px 14px}
.fl-gallery{padding-block:var(--feega-space-section)}
.fl-gallery .head{display:flex;flex-direction:column;align-items:flex-start;gap:var(--feega-space-6);margin-bottom:var(--feega-space-12)}
.fl-gallery .grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:var(--feega-space-3);padding:0;list-style:none}
.fl-gallery li{grid-column:span 2}
.fl-gallery li:nth-child(-n+2){grid-column:span 3}
.fl-gallery a{display:grid;gap:var(--feega-space-3)}
.fl-gallery .img{position:relative;display:grid;place-items:center;aspect-ratio:4/3;overflow:hidden;border-radius:var(--feega-radius-md);background-color:var(--feega-surface);color:var(--feega-fg-subtle);transition:transform var(--feega-dur) var(--feega-ease)}
.fl-gallery a:hover .img{transform:scale(0.985)}
.fl-gallery .img .fl-px{width:36px}
.fl-gallery .img em{position:absolute;left:12px;bottom:10px;font-family:var(--feega-font-mono);font-size:10px;font-style:normal;text-transform:uppercase}
.fl-gallery .cap{display:flex;justify-content:space-between;gap:var(--feega-space-3);font-size:var(--feega-text-sm)}
.fl-gallery .cap b{font-weight:500}
.fl-gallery .cap small{color:var(--feega-fg-subtle)}
@media (max-width:820px){.fl-gallery .grid{grid-template-columns:repeat(2,minmax(0,1fr))}.fl-gallery li,.fl-gallery li:nth-child(-n+2){grid-column:auto}.fl-gallery li:first-child{grid-column:1/-1}}
@media (max-width:480px){.fl-gallery .grid{grid-template-columns:minmax(0,1fr)}}
@media (prefers-reduced-motion:reduce){:where([class^="fl-"]) *,:where([class^="fl-"]) *::before,:where([class^="fl-"]) *::after{animation:none!important;transition:none!important}}
